let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_zmy2ul0s/app.log"
guard let content = try? String(contentsOfFile: path, encoding: .utf8) else {
    exit(1)
}

let lines = content.split(separator: "\n", omittingEmptySubsequences: true)

var levelCounts: [String: Int] = [:]
var componentErrors: [String: Int] = [:]
var uniqueErrorMessages: Set<String> = []
var hourCounts: [String: Int] = [:]

let pattern = "\\[(\\d{4}-\\d{2}-\\d{2}) (\\d{2}):\\d{2}:\\d{2}\\] (\\w+) \\(([^)]+)\\) - (.+)"
let regex = try! NSRegularExpression(pattern: pattern)

for line in lines {
    let str = String(line)
    guard let match = regex.firstMatch(in: str, options: [], range: NSRange(str.startIndex..., in: str)) else {
        continue
    }

    let hourRange = Range(match.range(at: 2), in: str)!
    let hour = String(str[hourRange])

    let levelRange = Range(match.range(at: 3), in: str)!
    let level = String(str[levelRange])

    let componentRange = Range(match.range(at: 4), in: str)!
    let component = String(str[componentRange])

    let messageRange = Range(match.range(at: 5), in: str)!
    let message = String(str[messageRange])

    levelCounts[level, default: 0] += 1
    hourCounts[hour, default: 0] += 1

    if level == "ERROR" {
        componentErrors[component, default: 0] += 1
        uniqueErrorMessages.insert(message)
    }
}

print("=== Log Analysis ===")
print("")
print("Entries by Level:")
for level in levelCounts.keys.sorted() {
    print("  \(level): \(levelCounts[level]!)")
}
print("")

if let topComponent = componentErrors.max(by: { $0.value < $1.value }) {
    print("Component with Most Errors: \(topComponent.key) (\(topComponent.value) errors)")
}
print("")

print("Unique Error Messages:")
for msg in uniqueErrorMessages.sorted() {
    print("  - \(msg)")
}
print("")

if let busiest = hourCounts.max(by: { $0.value < $1.value }) {
    print("Busiest Hour: \(busiest.key):00 (\(busiest.value) entries)")
}

