import json

def deep_merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        result = dict(a)
        for key in b:
            if key in result:
                result[key] = deep_merge(result[key], b[key])
            else:
                result[key] = b[key]
        return result
    elif isinstance(a, list) and isinstance(b, list):
        result = []
        for item in a + b:
            if item not in result:
                result.append(item)
        return result
    else:
        return b

