import Foundation

let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_zmy2ul0s/employees.csv"

guard let content = try? String(contentsOfFile: path, encoding: .utf8) else {
    fatalError("Cannot read file")
}

let lines = content.split(separator: "\n", omittingEmptySubsequences: true)
guard lines.count > 1 else { fatalError("No data") }

struct Employee {
    let id: String
    let name: String
    let department: String
    let salary: Double
}

var employees: [Employee] = []
for line in lines.dropFirst() {
    let fields = line.split(separator: ",", omittingEmptySubsequences: false).map { $0.trimmingCharacters(in: .whitespaces) }
    guard fields.count >= 4 else { continue }
    let emp = Employee(
        id: fields[0],
        name: fields[1],
        department: fields[2],
        salary: Double(fields[3]) ?? 0
    )
    employees.append(emp)
}

func formatComma(_ value: Double) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.maximumFractionDigits = 0
    formatter.minimumFractionDigits = 0
    return formatter.string(from: NSNumber(value: value)) ?? "\(Int(value))"
}

func formatComma2(_ value: Double) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.maximumFractionDigits = 2
    formatter.minimumFractionDigits = 2
    return formatter.string(from: NSNumber(value: value)) ?? String(format: "%.2f", value)
}

var deptSalaries: [String: [Double]] = [:]
var deptCount: [String: Int] = [:]
var totalBudget: Double = 0
var highestPaid: Employee? = nil

for emp in employees {
    deptSalaries[emp.department, default: []].append(emp.salary)
    deptCount[emp.department, default: 0] += 1
    totalBudget += emp.salary
    if highestPaid == nil || emp.salary > highestPaid!.salary {
        highestPaid = emp
    }
}

print("=== Salary Report ===")
print("")
print("Average Salary by Department:")
let sortedDepts = deptSalaries.keys.sorted()
for dept in sortedDepts {
    let salaries = deptSalaries[dept]!
    let avg = salaries.reduce(0, +) / Double(salaries.count)
    print("  \(dept): $\(formatComma2(avg))")
}
print("")
if let hp = highestPaid {
    print("Highest Paid: \(hp.name) ($\(formatComma(hp.salary)))")
}
print("")
print("Departments with >2 employees:")
let largeDepts = deptCount.filter { $0.value > 2 }.keys.sorted()
for dept in largeDepts {
    print("  \(dept) (\(deptCount[dept]!) employees)")
}
print("")
print("Total Budget: $\(formatComma(totalBudget))")

