import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_zmy2ul0s/app.log";
        Pattern pattern = Pattern.compile("^\\[\\d{4}-\\d{2}-\\d{2} (\\d{2}):\\d{2}:\\d{2}\\] (\\w+) \\(([^)]+)\\) - (.+)$");

        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> errorComponentCounts = new HashMap<>();
        Set<String> uniqueErrorMessages = new TreeSet<>();
        Map<String, Integer> hourCounts = new HashMap<>();

        BufferedReader reader = new BufferedReader(new FileReader(filePath));
        String line;
        while ((line = reader.readLine()) != null) {
            Matcher m = pattern.matcher(line);
            if (m.matches()) {
                String hour = m.group(1);
                String level = m.group(2);
                String component = m.group(3);
                String message = m.group(4);

                levelCounts.merge(level, 1, Integer::sum);
                hourCounts.merge(hour, 1, Integer::sum);

                if (level.equals("ERROR")) {
                    errorComponentCounts.merge(component, 1, Integer::sum);
                    uniqueErrorMessages.add(message);
                }
            }
        }
        reader.close();

        StringBuilder sb = new StringBuilder();
        sb.append("=== Log Analysis ===\n");
        sb.append("\n");
        sb.append("Entries by Level:\n");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            sb.append("  ").append(entry.getKey()).append(": ").append(entry.getValue()).append("\n");
        }
        sb.append("\n");

        String topErrorComponent = "";
        int topErrorCount = 0;
        for (Map.Entry<String, Integer> entry : errorComponentCounts.entrySet()) {
            if (entry.getValue() > topErrorCount || (entry.getValue() == topErrorCount && entry.getKey().compareTo(topErrorComponent) < 0)) {
                topErrorCount = entry.getValue();
                topErrorComponent = entry.getKey();
            }
        }
        sb.append("Component with Most Errors: ").append(topErrorComponent).append(" (").append(topErrorCount).append(" errors)\n");
        sb.append("\n");

        sb.append("Unique Error Messages:\n");
        for (String msg : uniqueErrorMessages) {
            sb.append("  - ").append(msg).append("\n");
        }
        sb.append("\n");

        String busiestHour = "";
        int busiestCount = 0;
        for (Map.Entry<String, Integer> entry : hourCounts.entrySet()) {
            if (entry.getValue() > busiestCount || (entry.getValue() == busiestCount && entry.getKey().compareTo(busiestHour) < 0)) {
                busiestCount = entry.getValue();
                busiestHour = entry.getKey();
            }
        }
        sb.append("Busiest Hour: ").append(busiestHour).append(":00 (").append(busiestCount).append(" entries)\n");

        System.out.print(sb.toString());
    }
}

