import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) throws IOException {
        String filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_zmy2ul0s/employees.csv";

        List<String[]> records = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line = br.readLine(); // skip header
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) continue;
                String[] parts = line.split(",");
                records.add(parts);
            }
        }

        TreeMap<String, List<Double>> deptSalaries = new TreeMap<>();
        double totalBudget = 0;
        String highestName = "";
        double highestSalary = -1;

        for (String[] rec : records) {
            String name = rec[1].trim();
            String dept = rec[2].trim();
            double salary = Double.parseDouble(rec[3].trim());

            deptSalaries.computeIfAbsent(dept, k -> new ArrayList<>()).add(salary);
            totalBudget += salary;

            if (salary > highestSalary) {
                highestSalary = salary;
                highestName = name;
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== Salary Report ===\n");
        sb.append("\n");
        sb.append("Average Salary by Department:\n");
        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            List<Double> salaries = entry.getValue();
            double sum = 0;
            for (double s : salaries) sum += s;
            double avg = sum / salaries.size();
            sb.append(String.format("  %s: $%,.2f%n", entry.getKey(), avg));
        }
        sb.append("\n");
        sb.append(String.format("Highest Paid: %s ($%,d)%n", highestName, (long) highestSalary));
        sb.append("\n");
        sb.append("Departments with >2 employees:\n");
        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            if (entry.getValue().size() > 2) {
                sb.append(String.format("  %s (%d employees)%n", entry.getKey(), entry.getValue().size()));
            }
        }
        sb.append("\n");
        sb.append(String.format("Total Budget: $%,d%n", (long) totalBudget));

        System.out.print(sb.toString());
    }
}

