#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE 4096
#define MAX_DEPTS 1000

typedef struct {
    char name[256];
    double sum;
    int count;
} Dept;

void format_commas(long long val, char *buf, int bufsize) {
    char temp[32];
    int neg = 0;
    if (val < 0) { neg = 1; val = -val; }
    snprintf(temp, sizeof(temp), "%lld", val);
    int len = (int)strlen(temp);
    int pos = 0;
    if (neg) buf[pos++] = '-';
    int first_group = len % 3;
    if (first_group == 0) first_group = 3;
    int i = 0;
    for (int j = 0; j < first_group && i < len; j++, i++) {
        buf[pos++] = temp[i];
    }
    while (i < len) {
        buf[pos++] = ',';
        for (int j = 0; j < 3 && i < len; j++, i++) {
            buf[pos++] = temp[i];
        }
    }
    buf[pos] = '\0';
}

void format_commas_double(double val, char *buf, int bufsize) {
    long long int_part = (long long)val;
    int frac = (int)((val - (double)int_part) * 100.0 + 0.5);
    if (frac < 0) frac = -frac;
    char comma_part[64];
    format_commas(int_part, comma_part, sizeof(comma_part));
    snprintf(buf, bufsize, "%s.%02d", comma_part, frac);
}

int cmp_dept(const void *a, const void *b) {
    Dept *da = (Dept *)a;
    Dept *db = (Dept *)b;
    return strcmp(da->name, db->name);
}

int find_dept(Dept *depts, int n, const char *name) {
    for (int i = 0; i < n; i++) {
        if (strcmp(depts[i].name, name) == 0) return i;
    }
    return -1;
}

int main(void) {
    const char *path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_zmy2ul0s/employees.csv";
    FILE *fp = fopen(path, "r");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    Dept *depts = malloc(MAX_DEPTS * sizeof(Dept));
    if (!depts) { fclose(fp); return 1; }
    int num_depts = 0;

    char *line = malloc(MAX_LINE);
    if (!line) { free(depts); fclose(fp); return 1; }

    /* skip header */
    if (!fgets(line, MAX_LINE, fp)) {
        free(line); free(depts); fclose(fp); return 0;
    }

    double total_budget = 0.0;
    double max_salary = -1.0;
    char max_name[256] = "";

    while (fgets(line, MAX_LINE, fp)) {
        /* remove trailing newline */
        size_t len = strlen(line);
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) {
            line[--len] = '\0';
        }
        if (len == 0) continue;

        /* parse: employee_id, name, department, salary, start_date, rating */
        char *fields[6];
        int nf = 0;
        char *tok = strtok(line, ",");
        while (tok && nf < 6) {
            fields[nf++] = tok;
            tok = strtok(NULL, ",");
        }
        if (nf < 6) continue;

        char *emp_name = fields[1];
        char *dept_name = fields[2];
        double salary = atof(fields[3]);

        total_budget += salary;

        if (salary > max_salary) {
            max_salary = salary;
            strncpy(max_name, emp_name, sizeof(max_name) - 1);
            max_name[sizeof(max_name) - 1] = '\0';
        }

        int idx = find_dept(depts, num_depts, dept_name);
        if (idx < 0) {
            idx = num_depts++;
