fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_zmy2ul0s/app.log";
    let content = fs::read_to_string(path).unwrap();

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut component_errors: HashMap<String, usize> = HashMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: HashMap<String, usize> = HashMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let close_bracket = match line.find(']') {
            Some(i) => i,
            None => continue,
        };
        let after_bracket = &line[close_bracket + 1..];
        let after_bracket = after_bracket.trim_start();

        // Find the level (first word)
        let space_pos = match after_bracket.find(' ') {
            Some(i) => i,
            None => continue,
        };
        let level = &after_bracket[..space_pos];

        // Find component in parentheses
        let paren_open = match after_bracket.find('(') {
            Some(i) => i,
            None => continue,
        };
        let paren_close = match after_bracket.find(')') {
            Some(i) => i,
            None => continue,
        };
        let component = &after_bracket[paren_open + 1..paren_close];

        // Find message after ") - "
        let dash_pos = match after_bracket.find(") - ") {
            Some(i) => i + 4,
            None => continue,
        };
        let message = &after_bracket[dash_pos..];

        // Count level
        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        // Count errors by component
        if level == "ERROR" {
            *component_errors.entry(component.to_string()).or_insert(0) += 1;
            error_messages.insert(message.to_string());
        }

        // Count by hour
        let ts_start = 1; // after '['
        if let Some(hour_str) = line.get(ts_start + 11..ts_start + 13) {
            let hour_key = format!("{}:00", hour_str);
            *hour_counts.entry(hour_key).or_insert(0) += 1;
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
