    let mut max_count = 0;
    let mut sorted_comps: Vec<(&String, &usize)> = component_errors.iter().collect();
    sorted_comps.sort_by(|a, b| a.0.cmp(b.0));
    for (comp, count) in &sorted_comps {
        if *count > max_count {
            max_count = *count;
            max_comp = comp.to_string();
        }
    }
    println!("Component with Most Errors: {} ({} errors)", max_comp, max_count);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    // Busiest hour
    let mut busiest_hour = String::from("00:00");
    let mut busiest_count = 0;
    let mut sorted_hours: Vec<(&String, &usize)> = hour_counts.iter().collect();
    sorted_hours.sort_by(|a, b| a.0.cmp(b.0));
    for (hour, count) in &sorted_hours {
        if *count > busiest_count {
            busiest_count = *count;
            busiest_hour = hour.to_string();
        }
    }
    println!("Busiest Hour: {} ({} entries)", busiest_hour, busiest_count);
