#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define PATH "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_zmy2ul0s/app.log"

typedef struct { char *name; int count; } CountEntry;
typedef struct { char *msg; } UniqueMsg;

static int cmp_count(const void *a, const void *b) {
    return strcmp(((const CountEntry*)a)->name, ((const CountEntry*)b)->name);
}
static int cmp_msg(const void *a, const void *b) {
    return strcmp(((const UniqueMsg*)a)->msg, ((const UniqueMsg*)b)->msg);
}

int main(void) {
    FILE *f = fopen(PATH, "r");
    if (!f) return 1;

    size_t bufcap = 4096;
    char *line = malloc(bufcap);
    if (!line) return 1;

    /* level counts */
    CountEntry *levels = NULL;
    int nlevels = 0, levels_cap = 0;

    /* component error counts */
    CountEntry *comperr = NULL;
    int ncomperr = 0, comperr_cap = 0;

    /* unique error messages */
    UniqueMsg *umsgs = NULL;
    int numsgs = 0, umsgs_cap = 0;

    /* hour counts: 0-23 */
    int hours[24] = {0};

    int total_entries = 0;

    while (getline(&line, &bufcap, f) != -1) {
        /* strip trailing newline */
        size_t len = strlen(line);
        while (len > 0 && (line[len-1]=='\n' || line[len-1]=='\r')) line[--len] = '\0';
        if (len == 0) continue;

        int year, month, day, hour, minute, sec;
        char level[64], component[256], message[4096];
        int parsed = sscanf(line, "[%d-%d-%d %d:%d:%d] %63s (%255[^)]) - %4095[^\n]",
                            &year, &month, &day, &hour, &minute, &sec,
                            level, component, message);
        if (parsed < 9) continue;

        total_entries++;
        hours[hour]++;

        /* level count */
        int found = 0;
        for (int i = 0; i < nlevels; i++) {
            if (strcmp(levels[i].name, level) == 0) { levels[i].count++; found = 1; break; }
        }
        if (!found) {
            if (nlevels >= levels_cap) {
                levels_cap = levels_cap ? levels_cap * 2 : 16;
                levels = realloc(levels, levels_cap * sizeof(CountEntry));
            }
            levels[nlevels].name = strdup(level);
            levels[nlevels].count = 1;
            nlevels++;
        }

        /* error-specific processing */
        if (strcmp(level, "ERROR") == 0) {
            /* component error count */
            int cf = 0;
            for (int i = 0; i < ncomperr; i++) {
                if (strcmp(comperr[i].name, component) == 0) { comperr[i].count++; cf = 1; break; }
            }
            if (!cf) {
                if (ncomperr >= comperr_cap) {
                    comperr_cap = comperr_cap ? comperr_cap * 2 : 16;
                    comperr = realloc(comperr, comperr_cap * sizeof(CountEntry));
                }
                comperr[ncomperr].name = strdup(component);
                comperr[ncomperr].count = 1;
                ncomperr++;
            }

            /* unique error message */
            int mf = 0;
            for (int i = 0; i < numsgs; i++) {
                if (strcmp(umsgs[i].msg, message) == 0) { mf = 1; break; }
            }
            if (!mf) {
                if (numsgs >= umsgs_cap) {
                    umsgs_cap = umsgs_cap ? umsgs_cap * 2 : 32;
                    umsgs = realloc(umsgs, umsgs_cap * sizeof(UniqueMsg));
                }
                umsgs[numsgs].msg = strdup(message);
                numsgs++;
            }
        }
    }
    fclose(f);
    free(line);

    /* sort levels alphabetically */
    qsort(levels, nlevels, sizeof(CountEntry), cmp_count);

    /* find component with most errors */
    int best_ci = 0;
    for (int i = 1; i < ncomperr; i++) {
        if (comperr[i].count > comperr[best_ci].count) best_ci = i;
    }

    /* sort unique error messages */
    qsort(umsgs, numsgs, sizeof(UniqueMsg), cmp_msg);

    /* find busiest hour */
    int best_h = 0;
    for (int i = 1; i < 24; i++) {
        if (hours[i] > hours[best_h]) best_h = i;
    }

    /* output */
    printf("=== Log Analysis ===\n");
    printf("\n");
    printf("Entries by Level:\n");
    for (int i = 0; i < nlevels; i++) {
        printf("  %s: %d\n", levels[i].name, levels[i].count);
    }
    printf("\n");
    if (ncomperr > 0) {
        printf("Component with Most Errors: %s (%d errors)\n", comperr[best_ci].name, comperr[best_ci].count);
    }
    printf("\n");
    printf("Unique Error Messages:\n");
    for (int i = 0; i < numsgs; i++) {
        printf("  - %s\n", umsgs[i].msg);
    }
    printf("\n");
    printf("Busiest Hour: %02d:00 (%d entries)\n", best_h, hours[best_h]);

    /* cleanup */
    for (int i = 0; i < nlevels; i++) free(levels[i].name);
    free(levels);
    for (int i = 0; i < ncomperr; i++) free(comperr[i].name);
    free(comperr);
    for (int i = 0; i < numsgs; i++) free(umsgs[i].msg);
    free(umsgs);

    return 0;
}

