import Foundation

func readJSON(path: String) -> Any {
    let data = try! Data(contentsOf: URL(fileURLWithPath: path))
    return try! JSONSerialization.jsonObject(with: data, options: [.fragmentsAllowed])
}

func canonicalKey(_ value: Any) -> String {
    if let dict = value as? [String: Any] {
        let sortedKeys = dict.keys.sorted()
        let parts = sortedKeys.map { "\($0):\(canonicalKey(dict[$0]!))" }
        return "{" + parts.joined(separator: ",") + "}"
    }
    if let arr = value as? [Any] {
        let parts = arr.map { canonicalKey($0) }
        return "[" + parts.joined(separator: ",") + "]"
    }
    if let num = value as? NSNumber {
        if CFGetTypeID(num) == CFBooleanGetTypeID() {
            return num.boolValue ? "true" : "false"
        }
        return num.stringValue
    }
    if let str = value as? String {
        return "\"\(str)\""
    }
    if value is NSNull {
        return "null"
    }
    return "\(value)"
}

func deepMerge(_ a: Any, _ b: Any) -> Any {
    if let aDict = a as? [String: Any], let bDict = b as? [String: Any] {
        var result = aDict
        for (key, bVal) in bDict {
            if let aVal = result[key] {
                result[key] = deepMerge(aVal, bVal)
            } else {
                result[key] = bVal
            }
        }
        return result
    }
    if let aArr = a as? [Any], let bArr = b as? [Any] {
        var result: [Any] = []
        var seen = Set<String>()
        for item in aArr + bArr {
            let key = canonicalKey(item)
            if !seen.contains(key) {
                seen.insert(key)
                result.append(item)
            }
        }
        return result
    }
    return b
}

func sortKeys(_ value: Any) -> Any {
    if let dict = value as? [String: Any] {
        var result: [String: Any] = [:]
        for key in dict.keys.sorted() {
            result[key] = sortKeys(dict[key]!)
        }
        return result
    }
    if let arr = value as? [Any] {
        return arr.map { sortKeys($0) }
    }
    return value
}

