    var minNode: String? = nil
    var minDist = Int.max
    for node in nodes {
        if !visited.contains(node) && dist[node]! < minDist {
            minDist = dist[node]!
            minNode = node
        }
    }
    guard let u = minNode else { break }
    visited.insert(u)
    for (v, w) in adj[u]! {
        if !visited.contains(v) && dist[u]! + w < dist[v]! {
            dist[v] = dist[u]! + w
        }
    }
}

