use std::fs;
use std::collections::HashMap;

fn parse_csv_line(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();

    while let Some(c) = chars.next() {
        if in_quotes {
            if c == '"' {
                if chars.peek() == Some(&'"') {
                    current.push('"');
                    chars.next();
                } else {
                    in_quotes = false;
                }
            } else {
                current.push(c);
            }
        } else {
            if c == '"' {
                in_quotes = true;
            } else if c == ',' {
                fields.push(current.clone());
                current.clear();
            } else {
                current.push(c);
            }
        }
    }
    fields.push(current);
    fields
}

fn format_comma_integer(n: u64) -> String {
    let s = n.to_string();
    let len = s.len();
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

fn format_money_2dp(n: f64) -> String {
    let integer_part = n.floor() as u64;
    let frac = n - integer_part as f64;
    let frac_str = format!("{:.2}", frac);
    let frac_digits = &frac_str[1..];
    format!("{}.{}", format_comma_integer(integer_part), frac_digits)
}

fn format_money_int(n: f64) -> String {
    format_comma_integer(n.round() as u64)
}

