typedef enum { JT_NULL, JT_BOOL, JT_NUM, JT_STR, JT_ARR, JT_OBJ } jtype;

typedef struct jnode {
    jtype type;
    char *str;
    double num;
    int boolean;
    struct jnode **children;
    char **keys;
    int count;
    int cap;
} jnode;

static jnode *jnode_new(jtype t) {
    jnode *n = (jnode *)malloc(sizeof(jnode));
    memset(n, 0, sizeof(jnode));
    n->type = t;
    return n;
}

static void jnode_add_child(jnode *n, jnode *child) {
    if (n->count >= n->cap) {
        n->cap = n->cap ? n->cap * 2 : 8;
        n->children = (jnode **)realloc(n->children, sizeof(jnode *) * n->cap);
    }
    n->children[n->count++] = child;
}

static void jnode_add_kv(jnode *n, const char *key, jnode *val) {
    if (n->count >= n->cap) {
        n->cap = n->cap ? n->cap * 2 : 8;
        n->children = (jnode **)realloc(n->children, sizeof(jnode *) * n->cap);
        n->keys = (char **)realloc(n->keys, sizeof(char *) * n->cap);
    }
    n->keys[n->count] = strdup(key);
    n->children[n->count] = val;
    n->count++;
}

