static char *parse_string_raw(parser *p) {
    /* p->pos points at opening quote */
    p->pos++; /* skip " */
    size_t cap = 64, len = 0;
    char *buf = (char *)malloc(cap);
    while (p->pos < p->len && p->data[p->pos] != '"') {
        if (p->pos + 1 >= p->len) break;
        if (p->data[p->pos] == '\\') {
            p->pos++;
            char c = p->data[p->pos];
            char out;
            switch (c) {
                case '"': out = '"'; break;
                case '\\': out = '\\'; break;
                case '/': out = '/'; break;
                case 'b': out = '\b'; break;
                case 'f': out = '\f'; break;
                case 'n': out = '\n'; break;
                case 'r': out = '\r'; break;
                case 't': out = '\t'; break;
                case 'u': {
                    /* parse 4 hex digits, encode as UTF-8 */
                    unsigned int cp = 0;
                    for (int i = 0; i < 4; i++) {
                        p->pos++;
                        char h = p->data[p->pos];
                        cp <<= 4;
                        if (h >= '0' && h <= '9') cp |= (h - '0');
                        else if (h >= 'a' && h <= 'f') cp |= (h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') cp |= (h - 'A' + 10);
                    }
                    /* handle surrogate pairs */
                    if (cp >= 0xD800 && cp <= 0xDBFF) {
                        p->pos++; /* skip backslash */
