                            p->pos++;
                            char h = p->data[p->pos];
                            lo <<= 4;
                            if (h >= '0' && h <= '9') lo |= (h - '0');
                            else if (h >= 'a' && h <= 'f') lo |= (h - 'a' + 10);
                            else if (h >= 'A' && h <= 'F') lo |= (h - 'A' + 10);
                        }
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                    }
                    /* encode UTF-8 */
                    if (cp < 0x80) {
                        if (len + 1 >= cap) { cap *= 2; buf = (char *)realloc(buf, cap); }
                        buf[len++] = (char)cp;
