            else {
                if (n->num == (long long)n->num && fabs(n->num) < 1e15)
                    fprintf(out, "%lld", (long long)n->num);
                else
                    fprintf(out, "%g", n->num);
            }
            break;
        case JT_STR: emit_string(out, n->str); break;
        case JT_ARR:
            if (n->count == 0) { fputs("[]", out); break; }
            fputs("[\n", out);
            for (int i = 0; i < n->count; i++) {
                for (int j = 0; j <= indent; j++) fputs("  ", out);
                emit_value(out, n->children[i], indent + 1);
                if (i < n->count - 1) fputc(',', out);
                fputc('\n', out);
            }
            for (int j = 0; j < indent; j++) fputs("  ", out);
            fputc(']', out);
            break;
        case JT_OBJ:
            if (n->count == 0) { fputs("{}", out); break; }
            /* sort keys */
            char **sorted_keys = (char **)malloc(sizeof(char *) * n->count);
            int *sorted_idx = (int *)malloc(sizeof(int) * n->count);
            for (int i = 0; i < n->count; i++) {
                sorted_keys[i] = n->keys[i];
                sorted_idx[i] = i;
            }
            /* sort indices by key */
            for (int i = 0; i < n->count - 1; i++) {
                for (int j = i + 1; j < n->count; j++) {
                    if (strcmp(sorted_keys[sorted_idx[i]], sorted_keys[sorted_idx[j]]) > 0) {
                        int tmp = sorted_idx[i];
                        sorted_idx[i] = sorted_idx[j];
                        sorted_idx[j] = tmp;
                    }
                }
            }
            fputs("{\n", out);
            for (int i = 0; i < n->count; i++) {
                int idx = sorted_idx[i];
                for (int j = 0; j <= indent; j++) fputs("  ", out);
                emit_string(out, n->keys[idx]);
                fputs(": ", out);
                emit_value(out, n->children[idx], indent + 1);
                if (i < n->count - 1) fputc(',', out);
                fputc('\n', out);
            }
            for (int j = 0; j < indent; j++) fputs("  ", out);
            fputc('}', out);
            free(sorted_keys);
            free(sorted_idx);
            break;
    }
}

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "Cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc(sz + 1);
    fread(buf, 1, sz, f);
    buf[sz] = '\0';
    fclose(f);
    *out_len = (size_t)sz;
    return buf;
}

