        int q2 = s.indexOf("\"", q1 + 1);
        return s.substring(q1 + 1, q2);
    }

    static int extractInt(String s, String key) {
        String search = "\"" + key + "\"";
        int idx = s.indexOf(search);
        int colon = s.indexOf(":", idx + search.length());
        int start = colon + 1;
        while (start < s.length() && s.charAt(start) != '-' && !Character.isDigit(s.charAt(start))) start++;
        int end = start;
        if (end < s.length() && s.charAt(end) == '-') end++;
        while (end < s.length() && Character.isDigit(s.charAt(end))) end++;
        return Integer.parseInt(s.substring(start, end));
    }
