use std::collections::{BinaryHeap, HashMap};
use std::cmp::Reverse;
use std::fs;

struct JsonParser {
    chars: Vec<char>,
    pos: usize,
}

impl JsonParser {
    fn new(s: &str) -> Self {
        JsonParser { chars: s.chars().collect(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        if self.pos < self.chars.len() { Some(self.chars[self.pos]) } else { None }
    }

    fn consume(&mut self, c: char) {
        assert_eq!(self.chars[self.pos], c, "Expected '{}' at pos {}", c, self.pos);
        self.pos += 1;
    }

    fn parse_string(&mut self) -> String {
        self.consume('"');
        let mut result = String::new();
        while self.pos < self.chars.len() && self.chars[self.pos] != '"' {
            if self.chars[self.pos] == '\\' {
                self.pos += 1;
                match self.chars[self.pos] {
                    'n' => result.push('\n'),
                    't' => result.push('\t'),
                    'r' => result.push('\r'),
                    '"' => result.push('"'),
                    '\\' => result.push('\\'),
                    '/' => result.push('/'),
                    _ => result.push(self.chars[self.pos]),
                }
            } else {
                result.push(self.chars[self.pos]);
            }
            self.pos += 1;
        }
        self.consume('"');
        result
    }

    fn parse_number(&mut self) -> i64 {
        self.skip_whitespace();
        let start = self.pos;
        if self.pos < self.chars.len() && self.chars[self.pos] == '-' {
            self.pos += 1;
        }
        while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
            self.pos += 1;
        }
        // skip decimal part if present
        if self.pos < self.chars.len() && self.chars[self.pos] == '.' {
            self.pos += 1;
            while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        s.parse::<i64>().unwrap_or(0)
    }

    fn parse_array_of_strings(&mut self) -> Vec<String> {
        self.consume('[');
        let mut result = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.pos += 1;
            return result;
        }
        loop {
            self.skip_whitespace();
            result.push(self.parse_string());
            self.skip_whitespace();
            if self.peek() == Some(',') {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.consume(']');
        result
    }

    fn parse_edges(&mut self) -> Vec<(String, String, i64)> {
        self.consume('[');
        let mut result = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.pos += 1;
            return result;
        }
        loop {
            self.skip_whitespace();
            self.consume('{');
            let mut from = String::new();
            let mut to = String::new();
            let mut weight: i64 = 0;
            // parse key-value pairs
            loop {
                self.skip_whitespace();
                if self.peek() == Some('}') {
                    self.pos += 1;
                    break;
                }
                let key = self.parse_string();
                self.skip_whitespace();
                self.consume(':');
                self.skip_whitespace();
                match key.as_str() {
                    "from" => from = self.parse_string(),
                    "to" => to = self.parse_string(),
                    "weight" => weight = self.parse_number(),
                    _ => {
                        // skip value
                        if self.peek() == Some('"') {
                            self.parse_string();
                        } else if self.peek() == Some('[') {
                            self.skip_to_matching(']', '[');
                        } else if self.peek() == Some('{') {
                            self.skip_to_matching('}', '{');
                        } else {
                            self.parse_number();
                        }
                    }
                }
                self.skip_whitespace();
                if self.peek() == Some(',') {
                    self.pos += 1;
                }
            }
            result.push((from, to, weight));
            self.skip_whitespace();
            if self.peek() == Some(',') {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.consume(']');
        result
    }

    fn skip_to_matching(&mut self, close: char, open: char) {
        self.consume(open);
        let mut depth = 1;
        while self.pos < self.chars.len() && depth > 0 {
            if self.chars[self.pos] == open { depth += 1; }
            if self.chars[self.pos] == close { depth -= 1; }
            self.pos += 1;
        }
    }

    fn parse_graph(&mut self) -> (Vec<String>, Vec<(String, String, i64)>) {
        self.skip_whitespace();
        self.consume('{');
        let mut nodes: Vec<String> = Vec::new();
        let mut edges: Vec<(String, String, i64)> = Vec::new();
        loop {
            self.skip_whitespace();
            if self.peek() == Some('}') {
                self.pos += 1;
                break;
            }
            let key = self.parse_string();
            self.skip_whitespace();
            self.consume(':');
            self.skip_whitespace();
            match key.as_str() {
                "nodes" => nodes = self.parse_array_of_strings(),
                "edges" => edges = self.parse_edges(),
                _ => {
                    if self.peek() == Some('[') {
                        self.skip_to_matching(']', '[');
                    } else if self.peek() == Some('{') {
                        self.skip_to_matching('}', '{');
                    } else if self.peek() == Some('"') {
                        self.parse_string();
                    } else {
                        self.parse_number();
                    }
                }
            }
            self.skip_whitespace();
            if self.peek() == Some(',') {
                self.pos += 1;
            }
        }
        (nodes, edges)
    }
}

fn main() {
    let content = fs::read_to_string(
        "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_zmy2ul0s/graph.json"
    ).expect("Failed to read graph file");

    let mut parser = JsonParser::new(&content);
    let (nodes, edges) = parser.parse_graph();

    // Build adjacency list (undirected)
    let mut adj: HashMap<String, Vec<(String, i64)>> = HashMap::new();
    for node in &nodes {
        adj.entry(node.clone()).or_insert_with(Vec::new);
    }
    for (from, to, weight) in &edges {
        adj.entry(from.clone()).or_insert_with(Vec::new).push((to.clone(), *weight));
        adj.entry(to.clone()).or_insert_with(Vec::new).push((from.clone(), *weight));
    }

    // Dijkstra from "A"
    let source = "A".to_string();
    let mut dist: HashMap<String, i64> = HashMap::new();
    for node in &nodes {
        dist.insert(node.clone(), i64::MAX);
    }
    dist.insert(source.clone(), 0);

    // Min-heap: (distance, node)
    let mut heap: BinaryHeap<Reverse<(i64, String)>> = BinaryHeap::new();
    heap.push(Reverse((0i64, source.clone())));

    while let Some(Reverse((d, u))) = heap.pop() {
        if d > *dist.get(&u).unwrap_or(&i64::MAX) {
            continue;
        }
        if let Some(neighbors) = adj.get(&u) {
            for (v, w) in neighbors {
                let nd = d + w;
                if nd < *dist.get(v).unwrap_or(&i64::MAX) {
                    dist.insert(v.clone(), nd);
                    heap.push(Reverse((nd, v.clone())));
                }
            }
        }
    }

    // Collect and sort nodes alphabetically
    let mut sorted_nodes: Vec<String> = nodes.clone();
    sorted_nodes.sort();

    // Output
    println!("=== Shortest Paths from A ===");
    println!();
    for node in &sorted_nodes {
        let d = dist.get(node).unwrap();
        if *d == i64::MAX {
            println!("{} -> {}: infinity", source, node);
        } else {
            println!("{} -> {}: {}", source, node, d);
        }
    }
}

