            buf = (char *)realloc(buf, buf_cap);
        }
    }
    close(sock);

    if (buf_len == 0) { free(buf); return NULL; }
    buf[buf_len] = '\0';

    char *body = strstr(buf, "\r\n\r\n");
    if (!body) { free(buf); return NULL; }
    body += 4;
    size_t body_len = buf_len - (size_t)(body - buf);

    char *result = (char *)malloc(body_len + 1);
    memcpy(result, body, body_len);
    result[body_len] = '\0';
    free(buf);
