    fclose(f);
    *out_len = len;
    return buf;
}

static void skip_ws(const char *s, long *pos, long len) {
    while (*pos < len && isspace((unsigned char)s[*pos])) (*pos)++;
}

static int match_char(const char *s, long *pos, long len, char c) {
    skip_ws(s, pos, len);
    if (*pos < len && s[*pos] == c) { (*pos)++; return 1; }
    return 0;
}

static int match_str(const char *s, long *pos, long len, const char *expect) {
    skip_ws(s, pos, len);
    long elen = (long)strlen(expect);
    if (*pos + elen <= len && strncmp(s + *pos, expect, elen) == 0) {
        *pos += elen;
        return 1;
    }
    return 0;
}

static char *parse_json_string(const char *s, long *pos, long len) {
