    long slen = *pos - start;
    char *result = (char *)malloc(slen + 1);
    memcpy(result, s + start, slen);
    result[slen] = '\0';
    if (*pos < len) (*pos)++; /* skip closing quote */
    return result;
}

static int parse_json_int(const char *s, long *pos, long len) {
    skip_ws(s, pos, len);
    int neg = 0;
    if (*pos < len && s[*pos] == '-') { neg = 1; (*pos)++; }
    int val = 0;
