    if (start < 0) { fprintf(stderr, "Node A not found\n"); return 1; }

    int *dist = (int *)malloc(node_count * sizeof(int));
    int *visited = (int *)calloc(node_count, sizeof(int));
    for (int i = 0; i < node_count; i++) dist[i] = INF;
    dist[start] = 0;

    /* Simple priority queue: linear scan */
    for (int iter = 0; iter < node_count; iter++) {
        int u = -1;
        int best = INF;
        for (int i = 0; i < node_count; i++) {
            if (!visited[i] && dist[i] < best) {
                best = dist[i];
                u = i;
            }
        }
        if (u == -1) break;
        visited[u] = 1;

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            int w = edges[e].weight;
            if (!visited[v] && dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
            }
        }
    }

    /* Sort nodes alphabetically */
    qsort(node_names, node_count, sizeof(char *), cmp_str);

    /* Output */
    printf("=== Shortest Paths from A ===\n\n");
    for (int i = 0; i < node_count; i++) {
        int idx = find_node_index(&(NodeSet){node_names, node_count}, node_names[i]);
        printf("%s -> %s: %d\n", "A", node_names[i], dist[idx]);
    }

    free(json);
    free(edges);
    free(node_names);
    free(dist);
    free(visited);
    return 0;
}

