import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Path root = Paths.get("/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_zmy2ul0s/project_tree");

        TreeMap<String, List<Path>> extFiles = new TreeMap<>();

        Files.walkFileTree(root, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path file, java.nio.file.attribute.BasicFileAttributes attrs) throws IOException {
                if (attrs.isRegularFile()) {
                    String name = file.getFileName().toString();
                    String ext = "";
                    int dotIdx = name.lastIndexOf('.');
                    if (dotIdx >= 0) {
                        ext = name.substring(dotIdx);
                    }
                    extFiles.computeIfAbsent(ext, k -> new ArrayList<>()).add(file);
                }
                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult visitFileFailed(Path file, IOException exc) throws IOException {
                return FileVisitResult.CONTINUE;
            }
        });

        System.out.println("=== File Tree Analysis ===");
        System.out.println();

        int totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<Path>> entry : extFiles.entrySet()) {
            String ext = entry.getKey();
            List<Path> files = entry.getValue();

            files.sort((a, b) -> {
                String ra = root.relativize(a).toString().replace('\\', '/');
                String rb = root.relativize(b).toString().replace('\\', '/');
                return ra.compareTo(rb);
            });

            long extLines = 0;
            long extChars = 0;
            List<String> fileInfos = new ArrayList<>();

            for (Path f : files) {
                byte[] data = Files.readAllBytes(f);
                long chars = data.length;
                long lines = 0;
                for (byte b : data) {
                    if (b == '\n') lines++;
                }
                String relPath = root.relativize(f).toString().replace('\\', '/');
                fileInfos.add(relPath + ": " + lines + " lines, " + chars + " chars");
                extLines += lines;
                extChars += chars;
            }

            System.out.println("Extension: " + ext);
            System.out.println("  Files: " + files.size());
            System.out.println("  Total Lines: " + extLines);
            System.out.println("  Total Characters: " + extChars);
            for (String info : fileInfos) {
                System.out.println("    " + info);
            }

            totalFiles += files.size();
            totalLines += extLines;
            totalChars += extChars;
        }

        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalChars + " characters");
    }
}

