let fm = FileManager.default

func walkDirectory(_ path: String) -> [String] {
    var files: [String] = []
    guard let contents = try? fm.contentsOfDirectory(atPath: path) else { return files }
    for item in contents.sorted() {
        let fullPath = path + "/" + item
        var isDir: ObjCBool = false
        if fm.fileExists(atPath: fullPath, isDirectory: &isDir) {
            // Check if it's a symlink
            if let attrs = try? fm.attributesOfItem(atPath: fullPath),
               let type = attrs[.type] as? FileManager.ItemType,
               type == .symbolicLink {
                continue
            }
            if isDir.boolValue {
                files.append(contentsOf: walkDirectory(fullPath))
            } else {
                files.append(fullPath)
            }
        }
    }
    return files
}

struct FileInfo {
    let relativePath: String
    let lines: Int
    let chars: Int
    let ext: String
}

let allFiles = walkDirectory(baseDir)

