static int nvisited = 0;
static int cap_visited = 0;

static int is_visited(dev_t dev, ino_t ino) {
    for (int i = 0; i < nvisited; i++) {
        if (visited[i].dev == dev && visited[i].ino == ino) return 1;
    }
    return 0;
}

static void mark_visited(dev_t dev, ino_t ino) {
    if (nvisited >= cap_visited) {
        cap_visited = cap_visited ? cap_visited * 2 : 64;
        visited = realloc(visited, cap_visited * sizeof(DirKey));
    }
    visited[nvisited].dev = dev;
    visited[nvisited].ino = ino;
    nvisited++;
