        if (strcmp(groups[i].ext, ext) == 0) return &groups[i];
    }
    if (ngroups >= cap_groups) {
        cap_groups = cap_groups ? cap_groups * 2 : 32;
        groups = realloc(groups, cap_groups * sizeof(ExtGroup));
    }
    ExtGroup *g = &groups[ngroups];
    g->ext = strdup(ext);
    g->files = NULL;
    g->nfiles = 0;
    g->cap = 0;
    g->total_lines = 0;
    g->total_chars = 0;
    ngroups++;
    return g;
}

static void add_file_to_group(ExtGroup *g, const char *relpath, long lines, long chars) {
    if (g->nfiles >= g->cap) {
        g->cap = g->cap ? g->cap * 2 : 16;
        g->files = realloc(g->files, g->cap * sizeof(FileInfo));
    }
    g->files[g->nfiles].relpath = strdup(relpath);
    g->files[g->nfiles].lines = lines;
    g->files[g->nfiles].chars = chars;
    g->nfiles++;
    g->total_lines += lines;
    g->total_chars += chars;
}

static int cmp_ext(const void *a, const void *b) {
    return strcmp(((ExtGroup *)a)->ext, ((ExtGroup *)b)->ext);
}

static int cmp_file(const void *a, const void *b) {
    return strcmp(((FileInfo *)a)->relpath, ((FileInfo *)b)->relpath);
}

static void count_file(const char *fullpath, long *lines, long *chars) {
    FILE *f = fopen(fullpath, "rb");
    if (!f) { *lines = 0; *chars = 0; return; }
