    *lines = l;
    *chars = c;
}

static void walk(const char *dirpath, const char *relprefix) {
    DIR *d = opendir(dirpath);
    if (!d) return;

    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;

        char fullpath[4096];
        snprintf(fullpath, sizeof(fullpath), "%s/%s", dirpath, ent->d_name);

        struct stat st;
        if (lstat(fullpath, &st) != 0) continue;

        if (S_ISLNK(st.st_mode)) continue;

        if (S_ISDIR(st.st_mode)) {
            if (is_visited(st.st_dev, st.st_ino)) continue;
            mark_visited(st.st_dev, st.st_ino);
            char newrel[4096];
            if (relprefix[0] == '\0')
                snprintf(newrel, sizeof(newrel), "%s", ent->d_name);
            else
                snprintf(newrel, sizeof(newrel), "%s/%s", relprefix, ent->d_name);
            walk(fullpath, newrel);
        } else if (S_ISREG(st.st_mode)) {
            char relpath[4096];
            if (relprefix[0] == '\0')
                snprintf(relpath, sizeof(relpath), "%s", ent->d_name);
            else
                snprintf(relpath, sizeof(relpath), "%s/%s", relprefix, ent->d_name);

            const char *dot = strrchr(ent->d_name, '.');
