function multiply(a: number[][], b: number[][]): number[][] {
    const n = a.length;
    const m = b[0].length;
    const p = b.length;
    const result: number[][] = [];
    for (let i = 0; i < n; i++) {
        result[i] = [];
        for (let j = 0; j < m; j++) {
            let sum = 0;
            for (let k = 0; k < p; k++) {
                sum += a[i][k] * b[k][j];
            }
            result[i][j] = sum;
        }
    }
    return result;
}

function determinant(m: number[][]): number {
    const n = m.length;
    if (n === 1) return m[0][0];
    if (n === 2) return m[0][0] * m[1][1] - m[0][1] * m[1][0];
    let det = 0;
    for (let j = 0; j < n; j++) {
        const minor: number[][] = [];
        for (let i = 1; i < n; i++) {
            const row: number[] = [];
            for (let k = 0; k < n; k++) {
                if (k !== j) row.push(m[i][k]);
            }
            minor.push(row);
        }
        det += (j % 2 === 0 ? 1 : -1) * m[0][j] * determinant(minor);
    }
    return det;
}

function formatMatrix(m: number[][]): string {
    return m.map(row => "  " + row.map(v => v.toString().padStart(4)).join(" ")).join("\n");
}

const A: number[][] = [[1, 2, 3], [4, 5, 6], [7, 8, 9]];
const B: number[][] = [[9, 8, 7], [6, 5, 4], [3, 2, 1]];
const C: number[][] = multiply(A, B);
const det: number = determinant(C);

const lines: string[] = [];
lines.push("=== Matrix Operations ===");
