use std::io::{Read, Write};
use std::net::TcpStream;

struct Parser {
    data: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Parser {
        Parser { data: s.chars().collect(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.data.len()
            && (self.data[self.pos] == ' '
                || self.data[self.pos] == '\t'
                || self.data[self.pos] == '\n'
                || self.data[self.pos] == '\r')
        {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.data.get(self.pos).copied()
    }

    fn eat(&mut self, c: char) {
        self.skip_ws();
        assert_eq!(self.data[self.pos], c);
        self.pos += 1;
    }

    fn parse_string(&mut self) -> String {
        self.eat('"');
        let mut result = String::new();
        while self.pos < self.data.len() {
            let c = self.data[self.pos];
            if c == '"' {
                self.pos += 1;
                return result;
            }
            if c == '\\' {
                self.pos += 1;
                let c2 = self.data[self.pos];
                match c2 {
                    'n' => result.push('\n'),
                    't' => result.push('\t'),
                    'r' => result.push('\r'),
                    '"' => result.push('"'),
                    '\\' => result.push('\\'),
                    '/' => result.push('/'),
                    'u' => {
                        self.pos += 4;
                        result.push('\u{FFFD}');
                    }
                    other => result.push(other),
                }
            } else {
                result.push(c);
            }
            self.pos += 1;
        }
        result
    }

    fn parse_number(&mut self) -> f64 {
        self.skip_ws();
        let start = self.pos;
        if self.pos < self.data.len() && (self.data[self.pos] == '-' || self.data[self.pos] == '+') {
            self.pos += 1;
        }
        while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() {
            self.pos += 1;
        }
        if self.pos < self.data.len() && self.data[self.pos] == '.' {
            self.pos += 1;
            while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        if self.pos < self.data.len() && (self.data[self.pos] == 'e' || self.data[self.pos] == 'E') {
            self.pos += 1;
            if self.pos < self.data.len() && (self.data[self.pos] == '-' || self.data[self.pos] == '+') {
                self.pos += 1;
            }
            while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        let s: String = self.data[start..self.pos].iter().collect();
        s.parse::<f64>().unwrap()
    }

    fn skip_value(&mut self) {
        self.skip_ws();
        match self.peek() {
            Some('"') => { self.parse_string(); }
            Some('{') => { self.skip_object(); }
            Some('[') => { self.skip_array(); }
            Some('t') => { self.pos += 4; }
            Some('f') => { self.pos += 5; }
            Some('n') => { self.pos += 4; }
            _ => { self.parse_number(); }
        }
    }

    fn skip_object(&mut self) {
        self.eat('{');
        self.skip_ws();
        if self.peek() == Some('}') { self.pos += 1; return; }
        loop {
            self.parse_string();
            self.eat(':');
            self.skip_value();
            self.skip_ws();
            if self.peek() == Some(',') {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.eat('}');
    }

    fn skip_array(&mut self) {
        self.eat('[');
        self.skip_ws();
        if self.peek() == Some(']') { self.pos += 1; return; }
        loop {
            self.skip_value();
            self.skip_ws();
            if self.peek() == Some(',') {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.eat(']');
    }

    fn parse_products(&mut self) -> Vec<(String, f64)> {
        self.eat('[');
        self.skip_ws();
        let mut products = Vec::new();
        if self.peek() == Some(']') {
            self.pos += 1;
            return products;
        }
        loop {
            self.eat('{');
            self.skip_ws();
            let mut name = String::new();
            let mut price = 0.0f64;
            if self.peek() == Some('}') {
                self.pos += 1;
            } else {
                loop {
                    let key = self.parse_string();
                    self.eat(':');
                    match key.as_str() {
                        "name" => name = self.parse_string(),
                        "price" => price = self.parse_number(),
                        _ => self.skip_value(),
                    }
                    self.skip_ws();
                    if self.peek() == Some(',') {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                self.eat('}');
            }
            products.push((name, price));
            self.skip_ws();
            if self.peek() == Some(',') {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.eat(']');
        products
    }
}

fn decode_chunked(body: &str) -> String {
    let chars: Vec<char> = body.chars().collect();
    let mut result = String::new();
    let mut pos = 0;
    loop {
        let mut size_str = String::new();
        while pos < chars.len() && chars[pos] != '\r' && chars[pos] != '\n' {
            size_str.push(chars[pos]);
            pos += 1;
        }
        // skip \r\n
        while pos < chars.len() && (chars[pos] == '\r' || chars[pos] == '\n') {
            pos += 1;
        }
        let size = match usize::from_str_radix(size_str.trim(), 16) {
            Ok(s) => s,
            Err(_) => break,
        };
        if size == 0 { break; }
        let chunk: String = chars[pos..pos + size].iter().collect();
        result.push_str(&chunk);
        pos += size;
        // skip trailing \r\n after chunk
        while pos < chars.len() && (chars[pos] == '\r' || chars[pos] == '\n') {
            pos += 1;
        }
    }
    result
}

fn main() {
    let mut stream = TcpStream::connect("127.0.0.1:18923").unwrap();
    let request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream.write_all(request.as_bytes()).unwrap();
    stream.flush().unwrap();

    let mut buf = Vec::new();
    stream.read_to_end(&mut buf).unwrap();
    let response = String::from_utf8_lossy(&buf).to_string();

    let header_end = response.find("\r\n\r\n").map(|i| i + 4).unwrap_or(0);
    let headers = &response[..header_end];
    let body = &response[header_end..];

    let json_body = if headers.to_lowercase().contains("transfer-encoding: chunked") {
        decode_chunked(body)
    } else {
        body.to_string()
    };

    let mut parser = Parser::new(&json_body);
    let products = parser.parse_products();

    let mut filtered: Vec<(String, f64)> = products
        .into_iter()
        .filter(|(_, p)| *p > 50.0)
        .collect();

    filtered.sort_by(|a, b| a.0.cmp(&b.0));

    println!("=== Filtered Products (price > $50.00) ===");
    println!();
    for (name, price) in &filtered {
        println!("{}: ${:.2}", name, price);
    }
    println!();
    println!("Count: {}", filtered.len());
    let total: f64 = filtered.iter().map(|(_, p)| p).sum();
    println!("Total: ${:.2}", total);
}

